// PolicyPlan Companion · Input Gate · companion-gate v1
// Validates the job from the app before any model runs. The webhook itself is
// protected by the "PolicyPlan webhook auth" header credential; this gate adds
// shape checks, a freshness window and a callback allowlist so results can
// only ever be posted back to an approved PolicyPlan host.
const VERSION = 'policyplan-companion-v1/1.2.0';
const b = ($input.first().json.body) || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const fail = (m) => { throw new Error('COMPANION_GATE/' + m); };

if (!['extract', 'write', 'story'].includes(b.stage)) fail('stage');
if (!UUID.test(b.job_id || '') || !UUID.test(b.case_id || '')) fail('ids');
if (!Number.isInteger(b.revision) || b.revision < 1) fail('revision');

// n8n's Code sandbox has no global URL, so parse the callback with a strict pattern.
const cb = /^https:\/\/([a-z0-9](?:[a-z0-9.-]*[a-z0-9])?)(\/[^?#\s@]*)$/i.exec(String(b.callback_url || '').trim());
if (!cb) fail(/^https:\/\//i.test(String(b.callback_url || '')) ? 'callback_url' : 'callback_not_https');
const host = cb[1].toLowerCase();
if (cb[2] !== '/api/companion/callback') fail('callback_path');
const allowed = String($vars.COMPANION_CALLBACK_HOSTS || '').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
if (!allowed.length) fail('COMPANION_CALLBACK_HOSTS_not_set');
if (!allowed.includes(host)) fail('callback_host_not_allowed:' + host);

const issued = Date.parse(b.issued_at || '');
const age = Date.now() - issued;
if (!Number.isFinite(issued) || age < -5 * 60 * 1000 || age > 30 * 60 * 1000) fail('stale_request');

if (b.stage === 'extract') {
  if (typeof b.illustration_text !== 'string' || b.illustration_text.length < 200 || b.illustration_text.length > 900000) fail('illustration_text');
  if (!/--- PAGE 1 ---/.test(b.illustration_text)) fail('page_markers');
}
if (b.stage === 'story') {
  // PolicyPlan Stories: one short writer call over the app's computed playback.
  if (!b.story_input || b.story_input.schema !== 'policyplan_story_input.v1') fail('story_input');
  if (!['apartment'].includes(b.story_input.story_key)) fail('story_key');
}
if (b.stage === 'write') {
  if (!b.writer_input || b.writer_input.schema !== 'companion_writer_input.v1') fail('writer_input');
  if (!b.analyst_input || b.analyst_input.schema !== 'companion_analyst_input.v1') fail('analyst_input');
}

return [{
  json: {
    stage: b.stage,
    job_id: b.job_id,
    case_id: b.case_id,
    revision: b.revision,
    callback_url: 'https://' + host + '/api/companion/callback',
    workflow_version: VERSION,
    prompt_versions: b.prompt_versions || null,
    illustration_text: b.stage === 'extract' ? b.illustration_text : null,
    writer_input: b.stage === 'write' ? b.writer_input : null,
    analyst_input: b.stage === 'write' ? b.analyst_input : null,
    story_input: b.stage === 'story' ? b.story_input : null,
  },
}];

// PolicyPlan Companion · Extract Result · v1
// Transport only: forwards the ATLAS envelope to the app, which builds and
// verifies the evidence itself. No insurance interpretation happens here.
const g = $('Companion Gate').first().json;
const env = $input.first().json || {};
if (!env.factSpine) throw new Error('COMPANION_EXTRACT/no_fact_spine');
return [{
  json: {
    callback_url: g.callback_url,
    callback: {
      stage: 'extract',
      job_id: g.job_id,
      case_id: g.case_id,
      revision: g.revision,
      status: 'ok',
      workflow_version: g.workflow_version,
      extraction: {
        atlas1: env.factSpine,
        atlas2: env.atlas2Parsed ?? null,
        atlas2_registry: env.atlas2EvidenceRegistry ?? null,
      },
    },
  },
}];

// PolicyPlan Companion · Writer Check · v1
// A light pre-check so a malformed answer gets one retry. The app re-parses
// strictly and runs the full claim guard; this node never repairs output.
const raw = String(($input.first().json || {}).output ?? '').trim();
const input = $('Companion Gate').first().json.writer_input || { blocks: [] };
let reason = '';
let j = null;
if (!raw.startsWith('{') || !raw.endsWith('}')) reason = 'not_a_single_json_object';
else {
  try { j = JSON.parse(raw); } catch (e) { reason = 'invalid_json'; }
}
if (!reason) {
  if (j.schema !== 'companion_writer.v1') reason = 'wrong_schema';
  else if (!Array.isArray(j.blocks) || !j.blocks.length) reason = 'no_blocks';
  else {
    const want = input.blocks.map((b) => b.block_id);
    const got = j.blocks.map((b) => b && b.block_id);
    const missing = want.filter((id) => !got.includes(id));
    if (missing.length) reason = 'missing_blocks:' + missing.join(',');
    const digits = j.blocks.filter((b) => /\d/.test(String(b.body || '').replace(/\{\{\s*f\.[a-z0-9_.]+\s*\}\}/g, ' ')));
    if (!reason && digits.length) reason = 'typed_numbers_in:' + digits.map((b) => b.block_id).join(',');
  }
}
return [{ json: { valid: !reason, reason, raw, attempt: 1 } }];

// PolicyPlan Companion · Write Result · v1
// Sends the raw writer text (and the analyst notes) to the app. The app is
// the authority: strict parse, token verification and the claim guard.
const g = $('Companion Gate').first().json;
const it = $input.first().json || {};
const fromCheck = typeof it.valid === 'boolean';
const raw = fromCheck ? it.raw : String(it.output ?? '');
let analyst = null;
try { analyst = $('Companion Analyst').first().json.output ?? null; } catch (e) { analyst = null; }
return [{
  json: {
    callback_url: g.callback_url,
    callback: {
      stage: 'write',
      job_id: g.job_id,
      case_id: g.case_id,
      revision: g.revision,
      status: 'ok',
      workflow_version: g.workflow_version,
      writer: { raw: String(raw).slice(0, 60000), analyst_raw: analyst == null ? null : String(analyst).slice(0, 20000), model: 'gpt-6.1-sol', attempts: fromCheck ? 1 : 2 },
    },
  },
}];

// PolicyPlan Story · Story Context · v1
// One place the story nodes read their job from. Two ways in:
//  · stage 'story' (generate again): the job came in on the webhook (checked by the gate);
//  · stage 'extract' with the form answers: the app answered the extract callback with
//    story_job, so the same run goes on to write the story. Nothing else triggers it.
const g = $('Companion Gate').first().json;
const r = $input.first().json || {};
const job = g.stage === 'story' ? { job_id: g.job_id, revision: g.revision, story_input: g.story_input } : r.story_job;
const ok = job && typeof job === 'object'
  && /^[0-9a-f-]{36}$/i.test(String(job.job_id))
  && Number.isInteger(job.revision) && job.revision > 0
  && job.story_input && job.story_input.schema === 'policyplan_story_input.v1'
  && ['apartment'].includes(job.story_input.story_key);
if (!ok) throw new Error('STORY_CONTEXT/invalid_story_job');
return [{
  json: {
    stage: 'story',
    job_id: String(job.job_id),
    case_id: g.case_id,
    revision: job.revision,
    callback_url: g.callback_url,
    workflow_version: g.workflow_version,
    story_input: job.story_input,
  },
}];

// PolicyPlan Story · Story Check · v1
// A light pre-check so a malformed answer gets one retry. The app re-parses
// strictly and runs the full wording and number guard; this node never repairs output.
const raw = String(($input.first().json || {}).output ?? '').trim();
const input = $('Story Context').first().json.story_input || {};
let reason = '';
let j = null;
if (!raw.startsWith('{') || !raw.endsWith('}')) reason = 'not_a_single_json_object';
else {
  try { j = JSON.parse(raw); } catch (e) { reason = 'invalid_json'; }
}
if (!reason) {
  if (j.schema !== 'policyplan_story.v1') reason = 'wrong_schema';
  else if (!j.story || typeof j.story.where_you_start !== 'string') reason = 'missing_story.where_you_start';
  else if (!Array.isArray(j.story.benefits) || !j.story.benefits.length) reason = 'missing_story.benefits';
  else if (!j.design || typeof j.design.headline !== 'string' || typeof j.design.takeaway !== 'string') reason = 'missing_design';
  else if (!Array.isArray(j.riders)) reason = 'missing_riders';
  else {
    const keys = j.story.benefits.map((b) => b && b.key);
    const need = ['growth', 'access', 'legacy'].filter((k) => !keys.includes(k));
    if (need.length) reason = 'missing_benefits:' + need.join(',');
    const known = (input.riders || []);
    const unknown = j.riders.filter((r) => !r || !known.includes(r.name));
    if (!reason && unknown.length) reason = 'unknown_riders';
  }
}
return [{ json: { valid: !reason, reason, raw, attempt: 1 } }];

// PolicyPlan Story · Story Result · v1
// Sends the raw writer text to the app. The app is the authority: strict
// parse, the wording guard and the number check against its own playback.
const g = $('Story Context').first().json;
const it = $input.first().json || {};
const fromCheck = typeof it.valid === 'boolean';
const raw = fromCheck ? it.raw : String(it.output ?? '');
return [{
  json: {
    callback_url: g.callback_url,
    callback: {
      stage: 'story',
      job_id: g.job_id,
      case_id: g.case_id,
      revision: g.revision,
      status: 'ok',
      workflow_version: g.workflow_version,
      story: { raw: String(raw).slice(0, 30000), model: 'gpt-6.1-sol', attempts: fromCheck ? 1 : 2 },
    },
  },
}];

// PolicyPlan Companion · Stage Failed · v1
// Any node error on either stage lands here, so the app never waits forever.
// Once the run has moved on to the story, a failure closes the story job, not the extract job.
const gate = $('Companion Gate').first().json;
let sc = null;
try {
  const n = $('Story Context');
  const j = n.isExecuted === false ? null : n.first().json;
  if (j && j.job_id && j.stage === 'story') sc = j;
} catch (e) {
  sc = null;
}
const g = sc || gate;
const e = $input.first().json || {};
const raw = e.error && (e.error.message || e.error.description || e.error) || e.message || 'workflow_error';
const error = String(raw).replace(/\s+/g, ' ').slice(0, 200);
return [{
  json: {
    callback_url: g.callback_url,
    callback: { stage: g.stage, job_id: g.job_id, case_id: g.case_id, revision: g.revision, status: 'error', workflow_version: g.workflow_version, error },
  },
}];

// PolicyPlan Companion · Prepare Callback · v1
// Serializes the body once. The exact same string is signed and sent.
const it = $input.first().json;
const raw = JSON.stringify(it.callback);
const ts = String(Math.floor(Date.now() / 1000));
return [{ json: { url: it.callback_url, raw, ts, signing_input: ts + '.' + raw } }];
